'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),path=require('node:path');
const input=JSON.parse(fs.readFileSync(path.join(__dirname,'model-input.json'),'utf8'));
const source=fs.readFileSync(path.join(__dirname,'source.rs'),'utf8');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex'),clone=x=>JSON.parse(JSON.stringify(x));
