function graph(){
 const records=input.documents.map((d,i)=>({id:'record:'+d.id,occurrenceId:d.id,kind:d.kind,text:d.text,graphNodeId:'item:portable:'+d.symbol,fileNodeId:'file:portable:source',file:'source.rs',sourceAbsolute:'/fixture/source.rs',range:i<4?null:{startByte:Buffer.byteLength(source.slice(0,source.indexOf(d.text))),endByte:Buffer.byteLength(source.slice(0,source.indexOf(d.text)+d.text.length)),begin:[1,0],end:[1,1],encoding:'synthetic geometry; Rust capture controls verify actual geometry'},declaration:{originalId:String(i+1),occurrenceId:d.id,path:'portable::'+d.symbol,kind:'function',file:'source.rs',begin:[1,0],end:[1,1],graphNodeId:'item:portable:'+d.symbol,hasBody:true},ownership:i<4?'compiler-original-occurrence':'exact-supported-body',sourceStatus:'matching-local-observation',sourceSha256:sha(source)}));
 const corpus={schemaVersion:1,extractor:'rust-comments-v1',scope:{packageId:'path+file:///portable#0.1.0',target:{name:'portable',kind:['lib'],source:'/fixture/source.rs'}},scopeSha256:sha('portable-scope'),artifactSha256:sha('synthetic-rustdoc-fixture'),buildSha256:sha('synthetic-build-fixture'),sourceSnapshotSha256:sha(source),exportStatus:'synthetic-engine-control; not compiler capture',sourcePins:[{file:'source.rs',status:'matching-local-observation',beforeSha256:sha(source),afterSha256:sha(source)}],records,coverage:{partial:true,hermeticSourceProof:false,diagnostics:['Synthetic engine carrier, not measured compiler capture; relevance vectors pending']}};
 const nodes=[{id:'crate:portable',label:'portable',attributes:{kind:'crate',crate:'portable',package_id:corpus.scope.packageId,workspace_member:'true'}},{id:'file:portable:source',label:'source.rs',source_file:'source.rs',attributes:{kind:'file',crate:'portable',package_id:corpus.scope.packageId}},...input.documents.map(d=>({id:'item:portable:'+d.symbol,label:d.symbol,source_file:'source.rs',source_location:1,attributes:{kind:'function',path:'portable::'+d.symbol,crate:'portable',package_id:corpus.scope.packageId,target_name:'portable',target_kind:'["lib"]',target_src_path:'/fixture/source.rs',source_absolute:'/fixture/source.rs'}})),{id:'item__portable__comment_corpus__metadata',label:'portable comments',attributes:{kind:'comment_corpus',crate:'portable',package_id:corpus.scope.packageId,comment_corpus:JSON.stringify(corpus)}}];
 return {nodes,edges:[],hyperedges:[],input_tokens:0,output_tokens:0};
}
function corpus(g){return JSON.parse(g.nodes.find(n=>n.attributes.kind==='comment_corpus').attributes.comment_corpus);}
